(() => {
  const btn=document.querySelector('#readBtn');
  if(!btn)return;
  const original=btn.onclick;
  const signs=['白羊座','金牛座','雙子座','巨蟹座','獅子座','處女座','天秤座','天蠍座','射手座','摩羯座','水瓶座','雙魚座'];
  const nak=['Ashwini','Bharani','Krittika','Rohini','Mrigashira','Ardra','Punarvasu','Pushya','Ashlesha','Magha','Purva Phalguni','Uttara Phalguni','Hasta','Chitra','Swati','Vishakha','Anuradha','Jyeshtha','Mula','Purva Ashadha','Uttara Ashadha','Shravana','Dhanishta','Shatabhisha','Purva Bhadrapada','Uttara Bhadrapada','Revati'];
  const coords={'香港':[22.3193,114.1694],'台北':[25.033,121.5654],'臺北':[25.033,121.5654],'深圳':[22.5431,114.0579],'廣州':[23.1291,113.2644],'澳門':[22.1987,113.5439]};
  function indian(){const birth=document.querySelector('#birthDate').value,time=document.querySelector('#birthTime').value||'12:00',place=document.querySelector('#birthPlace').value||'香港',q=document.querySelector('#question').value.trim()||'目前最重要的選擇';if(!birth||!document.querySelector('#gender').value){document.querySelector('#selectedNote').textContent='印度占星需要出生日期、出生時間及性別。';return null}const [y,m,d]=birth.split('-').map(Number),[hh,mm]=time.split(':').map(Number),date=new Date(`${birth}T${time}:00+08:00`),ayan=23.85+(y-2000)*0.01396,[lat,lon]=coords[place]||coords['香港'];if(typeof Astronomy==='undefined')return '天文計算庫未載入，未顯示任何假星盤資料。';const eqLon=body=>{const eq=Astronomy.Equator(body,date,true,true),ec=Astronomy.Ecliptic(eq,date);return ec.elon},tropical=body=>body==='Sun'?Astronomy.SunPosition(date).elon:eqLon(body),sid=body=>(tropical(body)-ayan+360)%360,sun=sid('Sun'),moon=sid('Moon'),mercury=sid('Mercury'),mars=sid('Mars'),jupiter=sid('Jupiter'),saturn=sid('Saturn'),moonIndex=Math.floor(moon/(360/27)),jd=2451545+(date.getTime()-Date.UTC(2000,0,1,12))/86400000,lst=(280.46061837+360.98564736629*(jd-2451545)+lon)%360,obl=23.4393*Math.PI/180,phi=lat*Math.PI/180,theta=lst*Math.PI/180,asc=(Math.atan2(-Math.cos(theta),Math.sin(theta)*Math.cos(obl)+Math.tan(phi)*Math.sin(obl))*180/Math.PI+360)%360,fmt=(label,v)=>`${label} ${v.toFixed(2)}°（${signs[Math.floor(v/30)%12]}）`,dasha=['Ketu','Venus','Sun','Moon','Mars','Rahu','Jupiter','Saturn','Mercury'][moonIndex%9];return `問題：「${q}」\n\n印度占星輸入：${birth} ${time} · ${document.querySelector('#gender').value==='male'?'男性':'女性／其他'} · ${place}（${lat}, ${lon}）\n\n計算版本：Astronomy Engine 2.1.19；Lahiri ayanamsa 近似 ${ayan.toFixed(2)}°。\n\n實際 Sidereal 行星位置：\n${fmt('太陽',sun)}\n${fmt('月亮',moon)}\n${fmt('水星',mercury)}\n${fmt('火星',mars)}\n${fmt('木星',jupiter)}\n${fmt('土星',saturn)}\n上升點 ${asc.toFixed(2)}°（${signs[Math.floor(asc/30)%12]}）\n\nNakshatra：${nak[moonIndex]}（第 ${moonIndex+1}/27）\nVimshottari Dasha 起始主星：${dasha}\n\n流年／流月／流日：${new Date().getFullYear()} 年、${new Date().getMonth()+1} 月、${new Date().getDate()} 日。\n\n問題行動：先將「${q}」拆成時間、風險及可控行動，再用 Transit／Dasha 作時間背景，唔將星盤當成必然預言。`}
  btn.onclick=()=>{const active=document.querySelector('.method.active');if(active&&active.dataset.name==='印度占星'){const text=indian();if(text){document.querySelector('#resultTitle').textContent='印度占星 · 實際星體資料';document.querySelector('#resultText').textContent=text+'\n\n判讀框架：先展示輸入、計算版本、實際位置及不確定性，再提供時間週期及問題行動框架。\n資料層：Sidereal 行星黃經、Lagna、Moon sign、Nakshatra、Vimshottari Dasha 起始主星、流年／流月／流日\n來源：https://github.com/cosinekitty/astronomy';document.querySelector('#readingPanel').classList.remove('is-open');document.querySelector('#resultCard').classList.add('is-open');document.querySelector('#resultCard').scrollIntoView({behavior:'smooth',block:'nearest'})}return}original()};
})();
